            if (Array.isArray(arr)) {
                var found = findInArray(arr, repoName);
                if (found) return found;
            }
        }
    }
    return null;
}

// ─── Main action ─────────────────────────────────────────────────────────────

function action(params) {
    var ticket = params.ticket;
    if (!ticket) {
        console.warn('resolveRepoFromTicket: no ticket in params — skipping repo resolution');
        return true;
    }

    var customParams = params.customParams
        || (params.jobParams && params.jobParams.customParams)
        || {};

    var strategyName = customParams.repoNameStrategy || 'fromSummary';
    var strategy = STRATEGIES[strategyName];
    if (!strategy) {
        console.warn('resolveRepoFromTicket: unknown strategy "' + strategyName +
            '" — available: ' + Object.keys(STRATEGIES).join(', ') + '. Skipping.');
        return true;
    }

    var repoName = strategy(ticket, customParams);
    if (!repoName) {
        console.warn('resolveRepoFromTicket: strategy "' + strategyName +
            '" could not resolve repo name from ticket ' + ticket.key + ' — skipping.');
        return true;
    }

    console.log('resolveRepoFromTicket: resolved repo "' + repoName +
        '" from ticket ' + ticket.key + ' via strategy "' + strategyName + '"');

    var entry = findRepoEntry(repoName, customParams.repositoriesFile);
    var targetRepository = { repo: repoName };

    if (entry) {
        if (entry.branch)       targetRepository.baseBranch = entry.branch;
        if (entry.gitlabGroup)  targetRepository.owner      = entry.gitlabGroup;
        // workingDir: explicit entry.workingDir → or derive from dependenciesDir/repoName
        // (checkout.sh clones repos into ./dependencies/{repo}/ by default)
        var dependenciesDir = customParams.dependenciesDir || './dependencies';
        targetRepository.workingDir = entry.workingDir || (dependenciesDir + '/' + repoName);
        console.log('resolveRepoFromTicket: repo entry found — branch=' +
            (entry.branch || 'n/a') + ', owner=' + (entry.gitlabGroup || 'n/a') +
            ', workingDir=' + targetRepository.workingDir);
    } else {
        console.warn('resolveRepoFromTicket: repo "' + repoName +
            '" not found in repositories file — forwarding repoName only');
    }

    // Mutate params so configLoader and preCliDevelopmentSetup pick it up downstream.
    // configLoader.loadProjectConfig is called as loadProjectConfig(params.jobParams || params),
    // so we write into both locations to cover both the Teammate and JSRunner call paths.
    if (!params.customParams) params.customParams = {};
    params.customParams.targetRepository = targetRepository;
    if (params.jobParams) {
        if (!params.jobParams.customParams) params.jobParams.customParams = {};
        params.jobParams.customParams.targetRepository = targetRepository;
    }

    return true;
}

if (typeof module !== 'undefined') {
    module.exports = { action: action, STRATEGIES: STRATEGIES, findRepoEntry: findRepoEntry };
}

/**
 * Recover Jira tickets whose GitHub PR was already merged while Jira stayed in
 * a review/rework status.
 */

const { LABELS } = require('./config.js');
var scmModule = require('./common/scm.js');
var configLoader = require('./configLoader.js');
var tokenUsageComment = require('./common/tokenUsageComment.js');

// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var trackersModule = require('./common/trackers.js');
var _trackerCtx = { config: null, customParams: {} };
var _trackerInst = null;
function initTracker(config, customParams) {
    _trackerCtx = { config: config || null, customParams: customParams || {} };
    _trackerInst = null;
}
function getTracker() {
    if (!_trackerInst) _trackerInst = trackersModule.createTracker(_trackerCtx.config, _trackerCtx.customParams);
    return _trackerInst;
}

function prMatchesTicket(pr, ticketKey) {
    if (!pr || !ticketKey) return false;
    var titleMatch = pr.title && pr.title.indexOf(ticketKey) !== -1;
    var branchMatch = pr.head && pr.head.ref && pr.head.ref.indexOf(ticketKey) !== -1;
    return !!(titleMatch || branchMatch);
}

function isMergedPR(pr) {
    if (!pr) return false;
    return !!(pr.merged_at || pr.mergedAt || pr.merge_commit_sha || pr.mergeCommit) ||
        pr.state === 'MERGED' ||
        pr.merged === true;
}

function findMergedPRForTicket(scm, ticketKey) {
    try {
        var open = scm.listPrs('open') || [];
        for (var openIndex = 0; openIndex < open.length; openIndex++) {
            if (prMatchesTicket(open[openIndex], ticketKey)) {
                console.log('Open PR still exists for ' + ticketKey + ', skipping merged-PR recovery: #' + open[openIndex].number);
                return null;
            }
        }
    } catch (openError) {
        console.warn('Could not list open PRs for merged recovery guard:', openError.message || openError);
        return null;
    }

    var closed = [];
    try {
        closed = scm.listPrs('closed') || [];
    } catch (e) {
        console.warn('Could not list closed PRs:', e.message || e);
        return null;
    }

    for (var i = 0; i < closed.length; i++) {
        if (prMatchesTicket(closed[i], ticketKey) && isMergedPR(closed[i])) {
            return closed[i];
        }
    }
    return null;
}

function removeLabel(ticketKey, label) {
    if (!ticketKey || !label) return;
    try {
        getTracker().removeLabel(ticketKey, label);
        console.log('Removed label from Jira:', label);
    } catch (e) {}
}

function action(params) {
    var ticketKey = params.ticket && params.ticket.key;
    if (!ticketKey) {
        console.error('No ticket key provided');
        return { success: false, action: 'missing_ticket' };
    }

    var config = configLoader.loadProjectConfig(params.jobParams || params);
    var jiraConfig = config.jira;
    initTracker(config, (params.jobParams && params.jobParams.customParams) || params.customParams || {});
    var scm = scmModule.createScm(config);
    var pr = findMergedPRForTicket(scm, ticketKey);

    if (!pr) {
        console.log('No merged PR found for', ticketKey);
        return { success: true, action: 'none' };
    }

    var prNumber = pr.number || pr.id || '?';
    var prUrl = pr.html_url || pr.url || '';
    console.log('Recovered merged PR #' + prNumber + ' for ' + ticketKey);

    try {
        // gh-916: MERGED can be tag-only (restricted ADO workflows) — stage-label fallback.
        var moveResult = getTracker().moveToStatusOrMark(ticketKey, jiraConfig.statuses.MERGED, 'MERGED');
        if (moveResult.moved || moveResult.marked) {
            console.log('Moved', ticketKey, 'to', jiraConfig.statuses.MERGED);
        }
    } catch (e) {
        console.warn('Could not move ticket to Merged:', e.message || e);
    }

    removeLabel(ticketKey, LABELS.PR_APPROVED);
    removeLabel(ticketKey, 'sm_pr_merge_triggered');
    removeLabel(ticketKey, 'sm_story_review_triggered');
    removeLabel(ticketKey, 'sm_story_rework_triggered');

    try {
        getTracker().postComment(ticketKey, 'h3. ✅ Merged PR Recovered\n\n' +
                'Found already merged PR #' + prNumber + (prUrl ? ' — [View PR|' + prUrl + ']' : '') +
                '. Ticket moved to *' + jiraConfig.statuses.MERGED + '* so the normal post-merge pipeline can continue.');
    } catch (e) {}

    // Post token usage summary comments (e.g. [story_acceptance_criteria]: {...}) if any provider
    // wrote outputs/*_usage.json during the agent run.
    try {
        tokenUsageComment.postTokenUsageComments(ticketKey, { initiator: params.initiator, customParams: tokenUsageComment.customParamsOf(params) });
    } catch (e) {
        console.warn('Failed to post token usage comments:', e);
    }

    return { success: true, action: 'moved_to_merged', prNumber: prNumber };
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action, findMergedPRForTicket, prMatchesTicket, isMergedPR };
}

/**
 * Restore From Releases — preJSAction
 *
 * Downloads named assets from a single shared Release per ticket (GitHub or
 * GitLab, resolved from config.scm.provider / customParams.scmProvider)
 * and unpacks them to configured local folders.
 * Always returns true (non-fatal) — if no release or asset exists yet, silently skips.
 *
 * customParams.restoreFromReleases schema:
 * {
 *   "releaseTagTemplate": "ai-{ticketKey}",   // optional, matches cacheToReleases default
 *   "assets": [
 *     {
 *       "name": "copilot-session",
 *       "toFolder": ".copilot/session-state/{ticketKey}"
 *     }
 *   ]
 * }
 *
 * Also requires customParams.artefactRepository: { owner, repo }
 * (falls back to aiRepository or targetRepository)
 *
 * Usage in agent config:
 *   "preJSAction": "agents/js/restoreFromReleases.js"
 */

var releaseArtefacts = require('./common/releaseArtefacts.js');
var configLoader = require('./configLoader.js');

function resolveCustomParams(params) {
    return (params.jobParams && params.jobParams.customParams) ||
           params.customParams ||
           {};
}

/**
 * @param {Object} params - Teammate/JSRunner params
 * @returns {boolean} Always true — non-fatal, never blocks processing
 */
function action(params) {
    try {
        var actualParams = params.ticket ? params : (params.jobParams || params);
        var ticketKey = actualParams.ticket && actualParams.ticket.key;
        if (!ticketKey) {
            console.warn('⚠️  restoreFromReleases: no ticketKey found, skipping');
            return true;
        }

        var customParams = resolveCustomParams(params);
        var config = customParams.restoreFromReleases;

        if (!config) {
            console.log('ℹ️  restoreFromReleases: not configured, skipping');
            return true;
        }

        var assets = config.assets;
        if (!assets || !Array.isArray(assets) || assets.length === 0) {
            console.log('ℹ️  restoreFromReleases: no assets configured, skipping');
            return true;
        }

        var artefactRepo = releaseArtefacts.resolveArtefactRepository(customParams);
        if (!artefactRepo) {
            console.warn('⚠️  restoreFromReleases: artefactRepository not configured, skipping');
            return true;
        }

        var projectConfig = configLoader.loadProjectConfig(actualParams);
        var scmProvider = (projectConfig.scm && projectConfig.scm.provider) || 'github';

        var releaseConfig = {
            tagTemplate:  config.releaseTagTemplate,
            nameTemplate: config.releaseNameTemplate
        };

        console.log('=== restoreFromReleases for', ticketKey, '(' + scmProvider + ') ===');
        console.log('Release tag:', releaseArtefacts.buildTag(ticketKey, releaseConfig.tagTemplate));

        for (var i = 0; i < assets.length; i++) {
            var asset = assets[i];
            if (!asset.name || !asset.toFolder) {
                console.warn('⚠️  Asset missing name or toFolder, skipping:', JSON.stringify(asset));
                continue;
            }

            var result = releaseArtefacts.downloadArtefact(
                artefactRepo.owner, artefactRepo.repo, ticketKey, releaseConfig, asset, scmProvider
            );

            if (result.restored) {
                console.log('✅ Restored "' + asset.name + '" →',
                            releaseArtefacts.resolveTemplate(asset.toFolder, ticketKey));
            } else if (!result.success) {
                console.warn('⚠️  Could not restore "' + asset.name + '":', result.error);
                // Non-fatal — continue to next asset
            }
        }

        console.log('=== restoreFromReleases done ===');

    } catch (e) {
        console.warn('⚠️  restoreFromReleases error (non-fatal):', e);
    }

    return true;
}

module.exports = { action: action };

