        './common/releaseArtefacts.js': releaseArtefactsMock,
        './configLoader.js': configLoaderMock
    });

    var mod = loadModule('js/restoreFromReleases.js', requireFn, {});
    mod._downloadArtefactCalls = downloadArtefactCalls;
